/*
 * <linux/input.h>: the input devices, /dev/input/event*: the keyboard, the tablet (the pointer) and
 * the PC speaker. A read gives whole struct input_events, and the EVIOC* requests ask a device what
 * it is and what it has.
 *
 * Part of the x86 Runtime library, written for the editor in the shape of Linux's own header: the
 * same names, values and layouts, with only what the editor's devices use.
 *
 * Generated by scripts/sim-header/generate.mjs from scripts/sim-header/deviceTable.mjs. Do not edit
 * it: regenerate it.
 */
#ifndef _LINUX_INPUT_H
#define _LINUX_INPUT_H

#if !defined(__x86_64__)
#error "This <linux/input.h> is the x86 one, included in a compilation for another Target"
#endif

#include <sys/time.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <linux/types.h>
#include <linux/input-event-codes.h>

/**
 * One event, 24 bytes, as a read of an input device gives it: a key going down, a move along one
 * axis, the end of a report. The events of one report end with an EV_SYN SYN_REPORT.
 */
struct input_event {
    /* When it happened, CLOCK_REALTIME unless EVIOCSCLOCKID chose another clock. */
    struct timeval time;
    __u16 type;  /* EV_KEY, EV_ABS, ... */
    __u16 code;  /* KEY_A, ABS_X, ... */
    __s32 value; /* For a key 1 down, 0 up and 2 a repeat; for an axis the position. */
};

/** Its seconds: event.input_event_sec. */
#define input_event_sec time.tv_sec

/** Its microseconds. */
#define input_event_usec time.tv_usec

#define EV_VERSION 0x10001 /* What EVIOCGVERSION answers. */

/** What EVIOCGID reads: who made the device and how it is connected. */
struct input_id {
    __u16 bustype; /* BUS_USB, BUS_I8042, ... */
    __u16 vendor;
    __u16 product;
    __u16 version;
};

/**
 * What EVIOCGABS reads for one axis: its value now and its range. Convert the tablet's x to a pixel
 * with (value * xres + 32766) / 32767.
 */
struct input_absinfo {
    __s32 value; /* The position now. */
    __s32 minimum;
    __s32 maximum;
    __s32 fuzz;
    __s32 flat;
    __s32 resolution;
};

/*
 * The requests. The ones with a len read up to len bytes into a buffer and return how many they
 * wrote; the bit sets have one bit per code, the lowest bit of the first byte for code 0.
 */
/* The evdev version, EV_VERSION, into an int. */
#define EVIOCGVERSION _IOR('E', 0x01, int)
#define EVIOCGID      _IOR('E', 0x02, struct input_id) /* The device's identity. */
/* The auto-repeat's delay and period in ms. */
#define EVIOCGREP     _IOR('E', 0x03, unsigned int[2])
#define EVIOCSREP     _IOW('E', 0x03, unsigned int[2]) /* Ask for another delay and period. */
#define EVIOCGKEYCODE _IOR('E', 0x04, unsigned int[2])
#define EVIOCSKEYCODE _IOW('E', 0x04, unsigned int[2])

/** The device's name, such as "AT Translated Set 2 keyboard". */
#define EVIOCGNAME(len) _IOC(_IOC_READ, 'E', 0x06, len)

/** Where the device is connected, such as "isa0060/serio0/input0". */
#define EVIOCGPHYS(len) _IOC(_IOC_READ, 'E', 0x07, len)

/** The device's serial number, if it has one. */
#define EVIOCGUNIQ(len) _IOC(_IOC_READ, 'E', 0x08, len)

/** The device's INPUT_PROP_* bits. */
#define EVIOCGPROP(len) _IOC(_IOC_READ, 'E', 0x09, len)

/**
 * The keys and buttons held now, one bit per code; it also discards the key events still queued for
 * this reader.
 */
#define EVIOCGKEY(len) _IOC(_IOC_READ, 'E', 0x18, len)

/** The lights lit now, one bit per LED_* code. */
#define EVIOCGLED(len) _IOC(_IOC_READ, 'E', 0x19, len)

/** The sounds playing now, one bit per SND_* code. */
#define EVIOCGSND(len) _IOC(_IOC_READ, 'E', 0x1a, len)
#define EVIOCGSW(len) _IOC(_IOC_READ, 'E', 0x1b, len)

/**
 * Which codes of the type ev the device has, one bit per code; with ev 0, which types it has, one
 * bit per EV_* type.
 */
#define EVIOCGBIT(ev, len) _IOC(_IOC_READ, 'E', 0x20 + (ev), len)

/** The value and range of the axis abs, into a struct input_absinfo. */
#define EVIOCGABS(abs) _IOR('E', 0x40 + (abs), struct input_absinfo)

/** Change the axis abs's struct input_absinfo. */
#define EVIOCSABS(abs) _IOW('E', 0xc0 + (abs), struct input_absinfo)

/* With 1, this reader alone gets the device's events; with 0, it lets go. */
#define EVIOCGRAB     _IOW('E', 0x90, int)
#define EVIOCREVOKE   _IOW('E', 0x91, int)
/* The clock of the event times: CLOCK_REALTIME, CLOCK_MONOTONIC or CLOCK_BOOTTIME. */
#define EVIOCSCLOCKID _IOW('E', 0xa0, int)

/* Where each part of a struct input_id is in an array of four __u16. */
#define ID_BUS     0
#define ID_VENDOR  1
#define ID_PRODUCT 2
#define ID_VERSION 3

/*
 * input_id's bustype. The keyboard is on BUS_I8042, the tablet on BUS_USB, the PC speaker on
 * BUS_ISA.
 */
#define BUS_PCI         0x1
#define BUS_ISAPNP      0x2
#define BUS_USB         0x3
#define BUS_HIL         0x4
#define BUS_BLUETOOTH   0x5
#define BUS_VIRTUAL     0x6
#define BUS_ISA         0x10
#define BUS_I8042       0x11
#define BUS_XTKBD       0x12
#define BUS_RS232       0x13
#define BUS_GAMEPORT    0x14
#define BUS_PARPORT     0x15
#define BUS_AMIGA       0x16
#define BUS_ADB         0x17
#define BUS_I2C         0x18
#define BUS_HOST        0x19
#define BUS_GSC         0x1a
#define BUS_ATARI       0x1b
#define BUS_SPI         0x1c
#define BUS_RMI         0x1d
#define BUS_CEC         0x1e
#define BUS_INTEL_ISHTP 0x1f
#define BUS_AMD_SFH     0x20

#endif
